def main():
    n, m = [int(c) for c in input().split()]
    a, b = input(), input()

    mod = 998244353
    N = 300009

    if n < m:
        a = '0' * (m - n) + a
    elif m < n:
        b = '0' * (n - m) + b

    n = max(n, m)
    one = [b[0] == '1']
    for i in range(1, n):
        one.append(one[-1] + (b[i] == '1'))

    pw = [1]
    for i in range(1, N):
        pw.append(pw[-1] * 2 % mod)

    ans = 0
    for i in range(n):
        res = (a[i] == '1') * pw[n - i - 1] % mod
        ans = (ans + res * one[i] % mod) % mod

    print(ans)


if __name__ == '__main__':
    main()

import math

def tree_search(l, u, x, a, b):
    if u == l:
        if check_upper(u, a, b, x):
            return u
        else:
            return u-1
    if u - l <= 1:
        if check_upper(u, a, b, x):
            return u
        elif check_upper(l, a, b, x):
            return l 
        else:
            return l-1

    m = (l+u)/2
    if check_upper(m, a, b, x):
        return tree_search(m, u, x, a, b)
    else:
        return tree_search(l, m, x, a, b)


dict_periodical = {}
def periodical(n):
    if n == 1:
        return 0

    if n in dict_periodical:
        return dict_periodical[n]

    total = 0
    for d in divisor(n):
        total = total + pow(2, d-1) - periodical(d)

    dict_periodical[n] = total
    return total

def check_upper(p, a, b, upper):
    mask = pow(2, a) - 1
    for i in range(b-1, -1,-1):
        converted = (upper >> i*a) & mask
        if converted > p:
            return True
        elif converted < p:
            return False
        else:
            continue
    return True

