class seg:
    def __init__(self, n):
        self.n = n
        m = 1
        while m < n: m *= 2
        self.m = m
        self.data = [0]*(2 * m)

    def add(self, ind):
        ind += self.m
        while ind:
            self.data[ind] += 1
            ind >>= 1

    def binary(self,k):
        ind = 1
        while ind < self.m:
            ind <<= 1
            if self.data[ind] < k:
                k -= self.data[ind]
                ind |= 1
        return ind - self.m

# This mergesort can be like 7 times faster than build in sort
# (for stupid reasons)
def mergesort(n, key, reverse=False):
    A = list(range(n))
    B = list(A)

    n = len(A)
    for i in range(0, n - 1, 2):
        if key(A[i]) > key(A[i ^ 1]):
            A[i], A[i ^ 1] = A[i ^ 1], A[i]

    width = 2
    while width < n:
        for i in range(0, n, 2 * width):
            R1, R2 = min(i + width, n), min(i + 2 * width, n)
            j, k = R1, i
            while i < R1 and j < R2:
                if key(A[i]) > key(A[j]):
                    B[k] = A[j]
                    j += 1
                else:
                    B[k] = A[i]
                    i += 1
                k += 1
            while i < R1:
                B[k] = A[i]
                k += 1
                i += 1
            while k < R2:
                B[k] = A[k]
                k += 1
        A, B = B, A
        width *= 2

    if reverse:
        A.reverse()
    return A

def main():
    n, m, q = [int(x) for x in input().split()]

    A = [int(x) for x in input().split()]

    hosts = [0.0]*m
    for a in A:
        hosts[a-1] += 1.0

    order = mergesort(m, hosts.__getitem__)
    years = []
    s = 0.0
    for before,i in enumerate(order):
        years.append(before * hosts[i] - s)
        s += hosts[i]

    big = 1000000000000
    big -= big % m
    bigf = float(big)

    def mapper(x):
        if len(x) <= 12:
            return float(x)
        return (int(x) % m) + bigf

    B = [mapper(x) - n - 1 for x in sys.stdin.buffer.read().split()]
    qorder = mergesort(q, B.__getitem__, reverse=True)
    ans = [0]*q

    segg = seg(m)
    for before,i in enumerate(order):
        segg.add(i)

        while qorder and (before == m-1 or years[before + 1] > B[qorder[-1]]):
            qind = qorder.pop()
            q = int((B[qind] - years[before]) % (before + 1))
            ans[qind] = segg.binary(q + 1) + 1
    print '\n'.join(str(x) for x in ans)


