def sieve_of_eratosthenes(n):
    min_fact = [1] * (n + 1)

    lst = [1] * (n+1)

    for p in range(2, n + 1):
        if min_fact[p] > 1:
            continue
        for i in range(p, n+1, p):
            min_fact[i] = p
            lst[i] *= 2

    return min_fact, lst


