        level = set([i])
        while(level):
            newLevel = set()
            for node in level:
                if(node in visited):
                    continue 
                visited.add(node)
                component.add(node)
                for neighbour in graph[node]:
                    newLevel.add(neighbour)
            level = newLevel 
        cnt = defaultdict(int)
        for idx in component:
