    t = I()

    pr = Prime(10**10)
    rr = []
    for _ in range(t):
        n = I()

        ii = pp = None
        for i in range(1, 10**3):
            t = i * (n-1)
            for p in pr.T:
                if p > t and not pr.is_prime(p-t):
                    pp = p - t
                    ii = i
                    break
            if pp:
                break

        a = [[ii] * n for _ in range(n)]
        for i in range(n):
            a[i][i] = pp

        rr.append(JAA(a, "\n", " "))

    return JA(rr, "\n")


