        xx, yy = -1, -1
        for i in range(2, n+1):
            qq.append(query('XOR', 1, i))
            if qq[-1] == 0:
                idx = i
            if qq[-1] in st:
                x, y = st[qq[-1]], i
            if qq[-1] == 1:
                xx = i
            if qq[-1] == 2:
                yy = i 
            st[qq[-1]] = i
        if idx != -1: 
            a = query('OR', 1, idx)
        elif x!=-1 and y!=-1:
            t = query('OR', x, y)
            a = t^qq[x-2]
        else:
            pre = query('OR', 1, xx)
            fix = query('AND', 1, yy)
            a = pre - pre%2 + fix%2
        ans = [a]
        for re in qq:
            ans.append(re^a)
        print '!', ' '.join(map(str, ans))
