def readGen(trans):
	while 1:
		for x in input().split():
			yield(trans(x))

readint=readGen(int)

[N,x,M,y]=(next(readint) for i in range(4))

d=abs(y-x)

def interval(a,b): return range(a,b+1)

def case1(N,M,d): # d>=N
	ans=0
	for r in interval(1, min(M,d-N)):
		ans+=1
	if (M<=d-N):
		return ans
	for r in interval(d-N+1, min(M,d)):
		ans+=2*(N+r-d)
	if (M<=d):
		return ans
	for r in interval(d+1,min(M,d+N)):
		ans+=2*(d+N-r+1)
	if (M<=d+N):
		return ans
	for r in interval(d+N+1,M):
		ans+=1
	return ans

def partA(N,M,d):
	ans=0
	for r in interval(1,min(M,d)):
		ans+=2*r-1
	if (M<d+1):
		return ans
	for r in interval(d+1,min(M,2*d)):
		ans+=2*(2*d-r)+1
	return ans

def partB(N,M,d):
	ans=0
	bound1=min(2*d,N-d)
	for r in interval(1,min(M,bound1)):
		ans+=2*(r-1)+1
	if (M<=bound1):
		return ans
	if (2*d<=N-d):
		for r in interval(bound1+1,min(M,N-d)):
			ans+=4*d
		if (M<=N-d):
			return ans
	if (2*d>N-d):
		for r in interval(bound1+1,min(M,2*d)):
			ans+=2*(N-d)+1
		if (M<=2*d):
			return ans
	bound2=max(2*d,N-d)
	for r in interval(bound2+1,min(M,d+N)):
		ans+=2*(d+N-r)+2
	if (M<=d+N):
		return ans
	for r in interval(d+N+1,M):
		ans+=1
	return ans

def case2(N,M,d): # d<N
	return partA(N,M,d)+partB(N,M,d)

def remain(N,M,d):
	if (M>=d+N):
		return 1
	if (M>d):
		return d+N-M+1
	if (M<=d):
		return N+1

def calc(N,M,d):
	if (N<=d): return remain(N,M,d)+case1(N,M,d)
	else: return remain(N,M,d)+case2(N,M,d)

print(calc(N,M,d))

import sys

MOD = (int)(1e9+7)

def add(a, b):
	a += b
	if a >= MOD: a -= MOD
	return a

def mul(a, b):
	return (a * b) % MOD

class fenwickTree:
	def __init__(self, max_val):
		self.max_val = max_val + 5
		self.tree = [0] * self.max_val

	def update(self, idx, value):
		idx += 1
		while idx < self.max_val:
			self.tree[idx] = add(self.tree[idx], value)
			idx += (idx & (-idx))

	def read(self, idx):
		idx += 1
		res = 0
		while idx > 0:
			res = add(res, self.tree[idx])
			idx -= (idx & (-idx))
		return res

inp = [int(x) for x in sys.stdin.read().split()]

n = inp[0]
a = []
for i in range(1, n + 1):
	a.append(inp[i])

sorted_array = sorted(a)
dict = {}
for i in range(n):
	dict[sorted_array[i]] = i

factor = [0] * n
for i in range(0, n):
	factor[i] = mul(i + 1, n - i)

left_tree = fenwickTree(n)
for i in range(0, n):
	element_idx = dict[a[i]]
	factor[i] = add(factor[i], mul(n - i, left_tree.read(element_idx)))
	left_tree.update(element_idx, i + 1)

right_tree = fenwickTree(n)
for i in range(n - 1, -1, -1):
	element_idx = dict[a[i]]
	factor[i] = add(factor[i], mul(i + 1, right_tree.read(element_idx)))
	right_tree.update(element_idx, n - i)

ans = 0
for i in range(n):
	ans = add(ans, mul(a[i], factor[i]))
print(ans)

from fractions import Fraction
import time


class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def to_tuple(self):
        return (self.x, self.y)

    def __repr__(self):
        return "Point({}, {})".format(self.x, self.y)

    def __eq__(self, other):
        return self.to_tuple() == other.to_tuple()

    def __hash__(self):
        return hash(self.to_tuple())

    def __neg__(self):
        return Point(-self.x, -self.y)

    def __add__(self, other):
        return Point(self.x+other.x, self.y+other.y)

    def __sub__(self, other):
        return self+(-other)

    def scalar_mul(self, mu):
        return Point(mu*self.x, mu*self.y)

    def int_divide(self, den):
        return Point(self.x//den, self.y//den)


class Line:
    def __init__(self, a, b, c):
        # ax+by+c=0
        self.a = a
        self.b = b
        self.c = c

    def __repr__(self):
        return "{}*x + {}*y + {} = 0".format(self.a, self.b, self.c)

    @classmethod
    def between_two_points(cls, P, Q):
        return cls(P.y-Q.y, Q.x-P.x, P.x*Q.y-P.y*Q.x)

    def evaluate(self, P):
        return self.a*P.x+self.b*P.y+self.c

    def direction(self):
        if self.a == 0:
            return (0, 1)
        return (1, Fraction(self.b, self.a))


def abs_sgn(x):
    if x == 0:
        return 0, 0
    if x < 0:
        return -x, -1
    return x, 1


def solve(tuple_points):
    points = set()
    center = Point(0, 0)
    for cur in tuple_points:
        cur = Point(*cur).scalar_mul(2*n)
        center += cur
        points.add(cur)

    center = center.int_divide(n)
    dcenter = center+center

    sym_points_set = set()
    for p in points:
        sym_points_set.add(dcenter-p)
    nosym = list(points - sym_points_set)

    if len(nosym) == 0:
        print(-1)
        exit(0)

    p0 = nosym[0]
    good_lines = set()
    for p in nosym:
        m = (p+p0).int_divide(2)
        line = Line.between_two_points(m, center)
        distances = list(map(line.evaluate, nosym))

        ok = True
        mydict = {}
        for dd in distances:
            dda, sgn = abs_sgn(dd)
            if dda not in mydict:
                mydict[dda] = sgn
            else:
                mydict[dda] += sgn
        for k in mydict:
            if mydict[k] != 0:
                ok = False
                break
        if ok:
            good_lines.add(line.direction())

    return len(good_lines)


