cities = []
memo = []
T = 0

class Node:
    def __init__(self, number, wayLen, wayTime, preNode):
        self.number, self.wayLen, self.wayTime, self.preNode = number, wayLen, wayTime, preNode

class Path:
    def __init__(self, wayLen, wayTime, nextNode):
        self.wayLen, self.wayTime, self.nextNode = wayLen, wayTime, nextNode 

def MemoizeWay2(endNode):
    global memo, T
    cNode = endNode
    while cNode.preNode != None: 
        cLLNode = memo[cNode.number].rootNode
        while cLLNode != None:
            tailLen = cLLNode.value.wayLen + 1
            tailTime = cLLNode.value.wayTime + cities[cNode.preNode.number][cNode.number]
            memo[cNode.preNode.number].Insert(Path(tailLen, tailTime, cNode.number))
            cLLNode = cLLNode.nextNode
        cNode = cNode.preNode

def MemoizeWay(endNode, tailLen, tailTime):
    global memo
    cNode = endNode
    while cNode.preNode != None:
        tailLen += 1
        tailTime += cities[cNode.preNode.number][cNode.number]
        b = memo[cNode.preNode.number].Insert(Path(tailLen, tailTime, cNode.number))
        if not b:
            break
        cNode = cNode.preNode


def main():
    global T, cities
    n, m, T = [int(s) for s in stdin.readline().split()]
    cities = [None] * (n+1)
    for i in range(m):
        u, v, t = [int(s) for s in stdin.readline().split()]
        if cities[u] == None:
            cities[u] = {}
        if u != n:
            cities[u].update({v : t})

    global memo
    memo = [LinkedList() for i in range(n+1)]
    memo[n].Insert(Path(1, 0, None))
    stack = []

    stack.append(Node(1, 1, 0, None))    
    while(len(stack) > 0):
        city = stack.pop()

        if city.number == n:
            MemoizeWay(city, 1, 0)
            continue

        if memo[city.number].rootNode != None:
            cNode = memo[city.number].rootNode
            while cNode != None:
                MemoizeWay(city, cNode.value.wayLen, cNode.value.wayTime)
                cNode = cNode.nextNode
            continue

        if cities[city.number] != None:
            for subCity in cities[city.number]:
                stack.append(Node( subCity, city.wayLen + 1, city.wayTime + cities[city.number][subCity], city ))

    cPath = memo[1].FindBestPath(T).value
    stdout.write( "{}\n".format(cPath.wayLen) )
    stdout.write( "{} ".format(1) )
    while(cPath.nextNode != None):
        stdout.write( "{} ".format(cPath.nextNode) )
        cPath = memo[cPath.nextNode].FindBestPath(cPath.wayTime).value


main()

import math
import itertools

pow10 = [1]
for i in range(10):
    pow10.append(pow10[-1] * 10)


def getlen(x):
    """length of the decimal representation of integer x"""
    return int(math.log10(x)) + 1


class ShortestRepresentation:

    def __init__(self, n):
        self.n = n
        self._m = {}
        self._s = [set() for i in range(10)]

        self._generate_powers()
        self._generate_power_and_power(7)
        self._generate_simple_and_power(7)

    def _generate_powers(self):
        """add to the collection all expressions of the form a^b"""
        range_x = itertools.takewhile(
            lambda x: x**2 <= self.n,
            itertools.count(2))
        for x in range_x:
            c = x**2
            p = 2
            while c <= self.n:
                self.update(c, '{}^{}'.format(x, p))
                c *= x
                p += 1

    def _generate_power_and_power(self, maxlen):
        """add to the collection all expressions of the form a^b*c^d"""
        for i in range(1, maxlen + 1):
            range_j = itertools.takewhile(
                lambda j: i + j + 1 <= maxlen,
                itertools.count(i))
            for j in range_j:
                for x, y in itertools.product(self._s[i], self._s[j]):
                    x2 = self.get(x)
                    y2 = self.get(y)
                    self.update(x * y, '{}*{}'.format(x2, y2))

    def _generate_simple_and_power(self, maxlen):
        """add to the collection all expressions of the form a^b*c"""
        for i in range(1, maxlen - 1):
            range_xy = itertools.product(
                range(1, pow10[maxlen - 1 - i]),
                self._s[i])
            for x, y in range_xy:
                y2 = self.get(y)
                self.update(x * y, '{}*{}'.format(x, y2))

    def update(self, x, s):
        """update with s x'th entry of the collection"""
        if x > self.n:
            return

        ls = len(s)
        if ls >= getlen(x):  # length of s should be at least shorter
            return

        if x not in self._m:
            self._m[x] = s
            self._s[ls].add(x)
        else:
            lm = len(self._m[x])
            if ls < lm:
                self._s[lm].remove(x)
                self._m[x] = s
                self._s[ls].add(x)

    def get(self, x):
        """retrieve shortest valid representation of number x"""
        return self._m[x] if x in self._m else str(x)


n = int(input())
if n < 10**10:
    sr = ShortestRepresentation(n)
    ans = sr.get(n)

    # check a*b and a+b
    range_i = itertools.takewhile(
        lambda i: i * 2 + 1 < len(ans),
        itertools.count())
    for i in range_i:
        range_x = itertools.chain(
            range(1, pow10[i] + 1),
            sr._s[i])
        for x in range_x:
            ans = min(
                ans, '{}+{}'.format(sr.get(x), sr.get(n - x)), key=len)
            if n % x > 0:
                continue
            ans = min(
                ans, '{}*{}'.format(sr.get(x), sr.get(n // x)), key=len)

    print(ans)
else:
    print('100^5')

