def solve(arr):
    alice = []
    bob = []
    for i in arr:
        if i % 2 == 0:
            alice.append(i)
        else:
            bob.append(i)

    alice.sort(reverse=True)
    bob.sort(reverse=True)

    aliceTmp = []
    bobTmp = []

    indexAlice = 0
    indexBOB = 0

    while indexAlice < len(alice) or indexBOB < len(bob) :
        maxAlice=0
        if indexAlice < len(alice):
            maxAlice = alice[indexAlice]

        maxBob = 0
        if indexBOB < len(bob):
            maxBob = bob[indexBOB]

        if maxAlice <= maxBob:
            indexBOB += 1
        else:
            if maxAlice != 0:
                aliceTmp.append(alice[indexAlice])
            indexAlice +=1

        maxAlice=0
        if indexAlice < len(alice):
            maxAlice = alice[indexAlice]

        maxBob = 0
        if indexBOB < len(bob):
            maxBob = bob[indexBOB]

        if maxBob <= maxAlice:
            indexAlice +=1
        else:
            if maxBob != 0:
                bobTmp.append(bob[indexBOB])
            indexBOB += 1

    sumAlice = sum(aliceTmp)
    sumBob = sum(bobTmp)

    if sumAlice > sumBob:
        print("Alice")
    else:
        if sumAlice < sumBob:
            print("Bob")
        else:
            print("Tie")



