import Queue

inFile = open("input.txt", 'r')
outFile = open("output.txt", 'w')

n, m, d = map(int, inFile.readline().strip().split(' '))
mat = map(lambda x: x.strip(), inFile.readlines())
mv = [(0, 1), (0, -1), (1, 0), (-1, 0)]

def findRats():
    ret = []
    for i in xrange(n):
        for j in xrange(m):
            if mat[i][j] == 'R':
                ret.append((i, j))
    return ret

def bfs(bgn, mat, d):
    q = Queue.Queue()
    q.put(bgn)
    c = {bgn:0}
    ret = set()
    while not q.empty():
        now = q.get()
        ret.add(now)
        if c[now] < d:
            for mi in mv:
                then = (now[0] + mi[0], now[1] + mi[1])
                if then[0] < n and then[0] >= 0 and \
                        then[1] < m and then[1] >= 0:
                    if mat[then[0]][then[1]] != 'X':
                        if then not in c:
                            q.put(then)
                            c[then] = c[now] + 1
    return ret

def find(firsts, locs):
    for first in firsts:
        others = []
        for loc in locs:
            if first not in loc:
                others.append(loc)
        if len(others) == 0:
            ans = [first]
            for i in xrange(n):
                for j in xrange(m):
                    if (i, j) != first:
                        if mat[i][j] != 'X':
                            ans.append((i, j))
                            return ans
            return -1
        seconds = reduce(lambda x, y: x & y, others)
        for second in seconds:
            if second != first:
                return (first, second)
    return -1

