        gr[u].append((v, c))
        gr[v].append((u, c))
    topo = list(topo_order(0))

    tree_size = [1 for i in range(n)]
    for u, p, _ in topo:
        if p is not None:
            tree_size[p] += tree_size[u]

    dp_up, dp_down = [0 for i in range(n)], [0 for i in range(n)]
