from collections import deque

def connected(n, arr):
    g = [[] for i in range(n)]
    for k in range(30):
        ind = []
        for i, a in enumerate(arr):
            if a&(1<<k):
                ind.append(i)
        if len(ind) > 1:
            a = ind.pop()
            for i in ind:
                g[i].append(a)
                g[a].append(i)
    v = [0]*n
    v[0] = 1
    q = deque()
    q.append(0)
    while q:
        x = q.popleft()
        for y in g[x]:
            if v[y] == 0:
                v[y] = 1
                q.append(y)
    return 0 not in v


