def good(oadd, arr, p):
    add = oadd
    range_ = (-1,-1)
    max_ = p
    min_ = -1
    digits = set(arr)
    for i in range(len(arr)):
        if add == 0:
            break
        val = (add%p + arr[i])
        add = add//p+val//p
        newval = val%p
        digits.add(newval)
        if val >= p:
            max_ = min(max_, arr[i])
            min_ = max(min_, newval)
        else:
            range_ = (arr[i],newval)
    if add:
        digits.add(add)
    i = min_+1
    while i < max_:
        if i == range_[0]:
            i = range_[1]+1
        elif i in digits:
            i += 1
        else:
            break
    return i >= max_

