	u, v = map(int, input().split())
	g[u-1].append(v-1)
	g[v-1].append(u-1)

stack = [0]
done = [False] * n
par = [0] * n
order = []
while len(stack) > 0:
	x = stack.pop()
	done[x] = True
	order.append(x)
	for i in g[x]:
		if done[i] == False:
			par[i] = x
			stack.append(i)
order = order[::-1]
sub = [0] * n
for i in order: 
	sub[i] = 1
	for j in g[i]:
		if par[j] == i:
			sub[i] += sub[j]

def good(guess):
	cnt = [0] * n
	for i in order:
		if a[i] < guess:
			continue
		cnt[i] = 1
		opt = 0
		for j in g[i]:
			if par[j] == i:
				if cnt[j] == sub[j]:
					cnt[i] += cnt[j]
				else:
					opt = max(opt, cnt[j])
		cnt[i] += opt
	if cnt[0] >= k:
		return True
	up = [0] * n
	for i in order[::-1]:
		if a[i] < guess:
			continue
		opt, secondOpt = 0, 0
		total = 1
		for j in g[i]:
			val, size = 0, 0
			if par[j] == i:
				val = cnt[j]
				size = sub[j]
			else:
				val = up[i]
				size = n - sub[i]
			if val == size:
				total += val
			else:
				if opt < val:
					opt, secondOpt = val, opt
				elif secondOpt < val:
					secondOpt = val

		for j in g[i]:
			if par[j] == i:
				up[j] = total
				add = opt
				if sub[j] == cnt[j]:
					up[j] -= cnt[j]
				elif cnt[j] == opt:
					add = secondOpt
				up[j] += add
	for i in range(n):
		if a[i] < guess:
			continue
		total, opt = 1, 0
		for j in g[i]:
			val, size = 0, 0
			if par[j] == i:
				val = cnt[j]
				size = sub[j]
			else:
				val = up[i]	
				size = n - sub[i]
			if val == size:
				total += val
			else:
				opt = max(opt, val)
		if total + opt >= k:
			return True			
	return False

l, r = 0, max(a)
while l < r:
	mid = (l + r + 1) // 2
	if good(mid):
		l = mid
	else:
		r = mid - 1
print(l)

# ------------------- fast io --------------------
from itertools import count
import os
import sys
from io import BytesIO, IOBase
import math

BUFSIZE = 8192


class FastIO(IOBase):
    newlines = 0

    def __init__(self, file):
        self._fd = file.fileno()
        self.buffer = BytesIO()
        self.writable = "x" in file.mode or "r" not in file.mode
        self.write = self.buffer.write if self.writable else None

    def read(self):
        while True:
            b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
            if not b:
                break
            ptr = self.buffer.tell()
            self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr)
        self.newlines = 0
        return self.buffer.read()

    def readline(self):
        while self.newlines == 0:
            b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
            self.newlines = b.count(b"\n") + (not b)
            ptr = self.buffer.tell()
            self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr)
        self.newlines -= 1
        return self.buffer.readline()

    def flush(self):
        if self.writable:
            os.write(self._fd, self.buffer.getvalue())
            self.buffer.truncate(0), self.buffer.seek(0)


class IOWrapper(IOBase):
    def __init__(self, file):
        self.buffer = FastIO(file)
        self.flush = self.buffer.flush
        self.writable = self.buffer.writable
        self.write = lambda s: self.buffer.write(s.encode("ascii"))
        self.read = lambda: self.buffer.read().decode("ascii")
        self.readline = lambda: self.buffer.readline().decode("ascii")


sys.stdin, sys.stdout = IOWrapper(sys.stdin), IOWrapper(sys.stdout)
input = lambda: sys.stdin.readline().rstrip("\r\n")

