def getMax(s,i,j,t,k,n):
    res = 0
    count = 0 
    while i<n :
        while j<n and count<k:
            if s[j]!=t:
                count+=1
            j+=1
        while j<n and s[j]==t:
            j+=1
        res = max(res,j-i)
        while i<n and s[i]==t:
            i+=1
        if i<n :
            i+=1
            count-=1
    return res

