    events.sort()
    opened = [0, 0]
    for item in events:
        color = item[2]
        action = item[1]
        if action == 0:
            if opened[(color + 1) % 2] > 0:
                return True
            opened[color] += 1
        else:
            opened[color] -= 1
    return False

