import sys
input = sys.stdin.readline

# TwoSat code from PyRival: https://github.com/cheran-senthil/PyRival/blob/9947ae98b7884614d98a5860764e85798c0cddfa/pyrival/data_structures/TwoSat.py
def find_SCC(graph):
    SCC, S, P = [], [], []
    depth = [0] * len(graph)

    stack = list(range(len(graph)))
    while stack:
        node = stack.pop()
        if node < 0:
            d = depth[~node] - 1
            if P[-1] > d:
                SCC.append(S[d:])
                del S[d:], P[-1]
                for node in SCC[-1]:
                    depth[node] = -1
        elif depth[node] > 0:
            while P[-1] > depth[node]:
                P.pop()
        elif depth[node] == 0:
            S.append(node)
            P.append(len(S))
            depth[node] = len(S)
            stack.append(~node)
            stack += graph[node]
    return SCC[::-1]

class TwoSat:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(2 * n)]

    def _imply(self, x, y):
        self.graph[x].append(y if y >= 0 else 2 * self.n + y)

    def either(self, x, y):
        """either x or y must be True"""
        self._imply(~x, y)
        self._imply(~y, x)

    def set(self, x):
        """x must be True"""
        self._imply(~x, x)

    def implies(self, x, y):
        self.either(~x, y)

    def solve(self):
        SCC = find_SCC(self.graph)
        order = [0] * (2 * self.n)
        for i, comp in enumerate(SCC):
            for x in comp:
                order[x] = i
        for i in range(self.n):
            if order[i] == order[~i]:
                return False, None
        return True, [+(order[i] > order[~i]) for i in range(self.n)]


class Helper:
    def __init__(self, i: int): self.i = i
    def __ge__(self, x: int): return self.i * (K+1) + x - 1
    def __lt__(self, x: int): return ~(self >= x)
    def __gt__(self, x: int): return self >= x + 1
    def __le__(self, x: int): return self < x + 1


out = []
for _ in range(int(input())):
    N, M, K = map(int, input().split())
    A = [Helper(i) for i in range(N)]
    ts = TwoSat(N*(K+1))

    for i in range(N):
        ts.set(A[i] >= 1)
        ts.set(A[i] <= K)

        for k in range(1, K):
            ts.implies(A[i] < k, A[i] < k+1)

        if i < N-1:
            for k in range(1, K+1):
                ts.implies(A[i] >= k, A[i+1] >= k)

    for _ in range(M):
        type, *args = map(int, input().split())
        if type == 1:
            i, x = args; i -= 1
            ts.either(A[i] < x, A[i] > x)
        else:
            i, j, x = args
            i -= 1; j -= 1

            if type == 2:
                for y in range(1, K+1):
                    if 1 <= x - y <= K:
                        ts.implies(A[i] >= y, A[j] <= x - y)
                        ts.implies(A[j] >= y, A[i] <= x - y)

                if x <= K:
                    ts.set(A[i] < x)
                    ts.set(A[j] < x)

            elif type == 3:
                for y in range(1, K+1):
                    if 1 <= x - y <= K:
                        ts.implies(A[i] <= y, A[j] >= x - y)
                        ts.implies(A[j] <= y, A[i] >= x - y)

                if x > K:
                    ts.set(A[i] >= x - K)
                    ts.set(A[j] >= x - K)

    ok, sol = ts.solve()
    if not ok:
        out.append("-1")
    else:
        ans = []
        for i in range(N):
            for k in range(K, 0, -1):
                if sol[A[i] >= k]:
                    ans.append(str(k))
                    break
            else:
                assert False

        out.append(" ".join(ans))

print("\n".join(out))

