def bfs(x, g):
    n, q = len(g), [x]
    dist = [0 if y == x else -1 for y in range(n)]
    i = 0
    while i < len(q):
        v = q[i]
        i += 1
        for to in g[v]:
            if dist[to] < 0:
                dist[to] = dist[v] + 1
                q.append(to)
    return (q[-1], dist[q[-1]])

