from sys import stdin


def task():
    value = stdin.readline()
    games = []
    counter = 0
    for i in xrange(1, len(value)-1):
        if value[i - 1] == value[i + 1]:
            counter += 1
        else:
            if counter > 0:
                games.append(counter)
            counter = 0
    if counter > 0:
        games.append(counter)
    max_game = max(games) if games else 0

    grundi = [0, 1, 1]
    for n in xrange(3, max_game + 1):
        s = {grundi[i] ^ grundi[n - i - 3] for i in xrange(0, n // 2 + 1)}
        s.add(grundi[n - 2])
        for i in xrange(n):
            if i not in s:
                grundi.append(i)
                break

    g = 0
    for game in games:
        g ^= grundi[game]
    print 'First' if g > 0 else 'Second'

    def check(n, g):
        if n < 3:
            return 0 if g == 0 else -1
        else:
            if grundi[n - 2] ^ g == 0:
                return 0
            for i in xrange(0, n - 2):
                if g ^ grundi[i] ^ grundi[n - i - 3] == 0:
                    return i + 1
            return -1

    cache = set()
    counter = 0
    delta = 0
    if g > 0:
        for i in xrange(1, len(value)-1):
            if value[i - 1] == value[i + 1]:
                if not delta:
                    delta = i + 1
                counter += 1
            else:
                if counter > 0:
                    if counter not in cache:
                        p = check(counter, grundi[counter] ^ g)
                        if p >= 0:
                            print delta + p
                            quit()
                        cache.add(counter)
                counter = 0
                delta = 0
        print delta + check(counter, grundi[counter] ^ g)

task()

