LENGHT = 4*10**3
PRIME_NUMB = 99999989
PRIME_NUMB2 = 999999937
from enum import Enum, auto
import random
import time

class Situation(Enum):
    EMPTY = auto
    DELETED = auto
    FILLED = auto

class HashTable():
    def __init__(self , lenght = LENGHT):
        self.lenght = lenght
        self.table = [[] for _ in range(lenght)]

    def __hash(self, value):
        return (value % PRIME_NUMB) % self.lenght
    def __hash2(self, value):
        return (value % PRIME_NUMB2) % self.lenght
    def __insert_linearProbe(self, value , i = 0):
        pos = (self.__hash(value) + i) % self.lenght
        if len(self.table[pos]) != 0 :
            if self.table[pos][0] == value :
                self.table[pos].append(value)
            elif self.table[pos][0] == Situation.DELETED :
                self.table[pos][0] = value
            else:
                self.__insert_linearProbe(value , i+1)
        else:
            self.table[pos].append(value)
    def __insert_squareProbe(self, value , i =0):
        c1 = 5
        c2 = 7
        pos = (self.__hash(value) + c2*i**2 + c1*i) % self.lenght
        if len(self.table[pos]) != 0 :
            if self.table[pos][0] == value :
                self.table[pos].append(value)
            elif self.table[pos][0] == Situation.DELETED :
                self.table[pos][0] = value
            else:
                self.__insert_squareProbe(value , i+1)
        else:
            self.table[pos].append(value)
    def __insert_binaryHash(self, value , i = 0):
        pos = (self.__hash(value) + i*self.__hash2(value)) % self.lenght
        if len(self.table[pos]) != 0 :
            if self.table[pos][0] == value :
                self.table[pos].append(value)
            elif self.table[pos][0] == Situation.DELETED :
                self.table[pos][0] = value
            else:
                self.__insert_binaryHash(value , i+1)
        else:
            self.table[pos].append(value)
    def __delete_linearProbe(self, value, i= 0):
        pos = (self.__hash(value) + i) % self.lenght
        v = 0
        while v < self.lenght:
            if len(self.table[pos]) != 0:
                if self.table[pos][0] == Situation.DELETED:
                    continue
                if self.table[pos][0] == value:
                    self.table[pos].remove(value)
                    if len(self.table[pos]) == 0:
                        self.table[pos].append(Situation.DELETED)
                    break
            v = v + 1
        raise Exception("this value was not inserted")
    def insert(self , value):
        self.__insert_linearProbe(value)

    def delete(self, value):
        self.__delete_linearProbe(value)
