def winner(A,B):
	if A==B:
		return -1
	if A==1 and B!=2:
		return 0
	if A==2 and B!=3:
		return 0
	if A==3 and B!=1:
		return 0
	if A!=2 and B==1:
		return 1 
	if A!=3 and B==2:
		return 1
	if A!=1 and B==3:
		return 1
	return -1

