def main():
    buf = input()
    n = int(buf)
    buf = input()
    buflist = buf.split()
    if n == 2 or n == 3:
        print(1) # corner
        return
    b = list(map(int, buflist))
    for i in range(n):
        b[i] = (b[i], i)
    b.sort()
    delta = []
    for i in range(n-1):
        delta.append(b[i+1][0] - b[i][0])
    deltamap = dict()
    for x in delta:
        if x in deltamap:
            deltamap[x] += 1
        else:
            deltamap[x] = 1
    if len(deltamap) == 1:
        print(b[0][1] + 1) # arithmetic progression already
        return
    #print(delta)
    #print(deltamap, len(deltamap))
    zero_candidate = []
    norm_candidate = []
    for k, v in deltamap.items():
        if v == n - 2:
            zero_candidate.append(k)
        elif v == n - 3:
            norm_candidate.append(k)
    if zero_candidate:
        if delta[0] != zero_candidate[0]:
            print(b[0][1] + 1) # delete first
            return
        elif delta[-1] != zero_candidate[0]:
            print(b[-1][1] + 1) # delete last
            return
        elif 0 in deltamap:
            if zero_candidate[0] == 0:
                print(-1)
                return
            for i, x in enumerate(delta):
                if x == 0:
                    print(b[i][1] + 1) # delete same num
                    return
        print(-1) # impossible
        return
    elif norm_candidate:
        if 0 in deltamap:
            print(-1)
            return
        for x in norm_candidate:
            for i in range(n-2):
                if delta[i] + delta[i+1] == x:
                    print(b[i+1][1] + 1)
                    return
        print(-1) # impossible
        return
    else:
        print(-1) # impossible
        return

if __name__ == '__main__':
    main()

