def ro(lis,rot,p,n,m):
    if rot==1:
        for k in range(p):
            lis[k]=(lis[k][1],n+1-lis[k][0])
    if rot==2:
        for k in range(p):
            lis[k]=(n+1-lis[k][0],m+1-lis[k][1])
    if rot==3:
        for k in range(p):
            lis[k]=(m+1-lis[k][1],lis[k][0])
