def main():
    n, m = map(int, stdin.readline().split())
    adj = [[] for _ in range(n)]
    for _ in range(m):
        v, u = map(int, stdin.readline().split())
        adj[v - 1].append(u - 1)
        adj[u - 1].append(v - 1)
    check = [False] * n
    stack = []
    count = 0
    for i in range(n):
        if not check[i]:
            first = i
            cycle = 1
            stack = [(i, -1)]

            while stack:
                c, p = stack.pop()
                if check[c]:
                    continue
                else:
                    check[c] = True
                    if len(adj[c]) > 2 or len(adj[c]) <= 1:
                        cycle = 0
                    for nb in adj[c]:
                        if nb != p:
                            stack.append((nb, i))
            count += cycle
    print(count)


