import math
def balanced(m,l):

    leftMax = float("-inf")
    rightMax = float("-inf")


    for i in l:
        if i>m:
            rightMax = max(max(l[i]) + i-m,rightMax)
        elif i<m:
            leftMax = max(max(l[i]) + m-i,leftMax)

    return rightMax-leftMax


