def solve(a,b):
    j = 1
    di = {}
    for i in range(len(a)):
        while j < b[i]:
            di[j] = i
            j+=2
    ans = 2*len(a) + 1
    for i in range(len(a)):
        ans = min(ans, i + di[a[i]])
    return ans


