    q = deque()
    # vis = {}
    for i in range(1,n+1):
        if indeg[i]==0:
            q.append(i)
            # vis[i] = 1
    cnt = 0
    top = []
    while q:
        s = q.popleft()
        top.append(s)
        for i in gr0[s]:
            indeg[i]-=1
            if indeg[i]==0:
                q.append(i)
        cnt+=1

    if cnt!=n:
        print("NO")
