    mp = {}
    for i in range(n):
        mp[top[i]] = i
    for x,y in edges:
        if mp[x]<mp[y]:
            gr0[x].append(y)
        else:
            gr0[y].append(x)
    print("YES")
    for i in gr0.keys():
        for j in gr0[i]:
