def greedy(x, y, rev=False):
    i, j = len(x) - 1, len(y) - 1
    swaps = []
    while True:
        while i >= 0 and x[i] == 'a':
            i -= 1
        while j >= 0 and y[j] == 'b':
            j -= 1
        if i < 0 and j < 0:
            break
        x, y = y, x
        if rev:
            swaps.append((j + 1, i + 1))
        else:
            swaps.append((i + 1, j + 1))
        i, j = j, i
    return swaps

def solve(x, y):
    p = greedy(x, y)
    q = greedy(y, x, True)
    if len(p) < len(q):
        return p
    return q

