import itertools


def check(combination, enemies):
    for a in combination:
        for b in combination:
            if a != b:
                if (a, b) in enemies or (b, a) in enemies:
                    return False
    return True


def main():
    n, m = map(int, raw_input().split())
    names = [raw_input() for i in xrange(n)]
    enemies = set([tuple(raw_input().split()) for i in xrange(m)])

    for size in reversed(xrange(1, n + 1)):
        for combination in itertools.combinations(names, size):
            if check(combination, enemies):
                print size
                for x in sorted(combination):
                    print x
                return


if __name__ == '__main__':
    main()

import os
import sys
from io import BytesIO, IOBase

BUFSIZE = 8192

class FastIO(IOBase):
    newlines = 0

    def __init__(self, file):
        self._fd = file.fileno()
        self.buffer = BytesIO()
        self.writable = "x" in file.mode or "r" not in file.mode
        self.write = self.buffer.write if self.writable else None

    def read(self):
        while True:
            b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
            if not b:
                break
            ptr = self.buffer.tell()
            self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr)
        self.newlines = 0
        return self.buffer.read()

    def readline(self):
        while self.newlines == 0:
            b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
            self.newlines = b.count(b"\n") + (not b)
            ptr = self.buffer.tell()
            self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr)
        self.newlines -= 1
        return self.buffer.readline()

    def flush(self):
        if self.writable:
            os.write(self._fd, self.buffer.getvalue())
            self.buffer.truncate(0), self.buffer.seek(0)


class IOWrapper(IOBase):
    def __init__(self, file):
        self.buffer = FastIO(file)
        self.flush = self.buffer.flush
        self.writable = self.buffer.writable
        self.write = lambda s: self.buffer.write(s.encode("ascii"))
        self.read = lambda: self.buffer.read().decode("ascii")
        self.readline = lambda: self.buffer.readline().decode("ascii")


sys.stdin, sys.stdout = IOWrapper(sys.stdin), IOWrapper(sys.stdout)
input = lambda: sys.stdin.readline().rstrip("\r\n")

from collections import defaultdict as dd
from collections import deque
import bisect
import heapq

def ri():
    return int(input())

def rl():
    return list(map(int, input().split()))


def solve():
    n = ri()
    H = rl()
    G = dd(list)
    P = dd(lambda:-1)
    for i in range(n - 1):
        u, v = rl()
        u -= 1
        v -= 1
        G[u].append(v)
        G[v].append(u)

    root = 0
    highest = 0
    for i in range(n):
        if H[i] > highest:
            root = i
            highest = H[i]

    P[root] = root
    curr = [root]
    while curr:
        node = curr.pop()
        for nbr in G[node]:
            if P[nbr] == -1:
                P[nbr] = node
                curr.append(nbr)

    maxbelow = [0] * n
    # def dfs(u):
        # for v in G[u]:
            # if v != P[u]:
                # dfs(v)
                # maxbelow[u] = max(maxbelow[u], maxbelow[v], H[v])
# 
        # 
    # dfs(root)

    layers = [root]
    curr = [root]
    while curr:
        nxt = []
        for node in curr:
            for nbr in G[node]:
                if nbr != P[node]:
                    nxt.append(nbr)
        layers += nxt
        curr = nxt

    for u in layers[::-1]:
        for v in G[u]:
            if v != P[u]:
                maxbelow[u] = max(maxbelow[u], maxbelow[v], H[v])

    ans = 0
    for i in range(n):
        if i == root: continue
        ans += max(0, H[i] - maxbelow[i])

    paths = []
    for v in G[root]:
        paths.append(max(H[v], maxbelow[v]))
    if len(paths) == 1:
        ans += H[root] + H[root] - paths[0]
    else:
        paths.sort()
        ans += 2 * H[root] - paths[-1] - paths[-2]
    print (ans)



